<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $activity_id = absint( $args['activity_id'] ); $favorite = ! empty( $args['favorite'] ); $saved = function_exists( 'sd_core_saved_activity_ids' ) && in_array( $activity_id, sd_core_saved_activity_ids(), true ); ?><div class="sd-activity-actions"><button type="button" data-sd-favorite="<?php echo esc_attr( $activity_id ); ?>" aria-pressed="<?php echo $favorite ? 'true' : 'false'; ?>"><?php echo $favorite ? '♥' : '♡'; ?> <span><?php esc_html_e( 'Favorite', 'social-discovery' ); ?></span></button><button type="button" data-sd-comment-focus="<?php echo esc_attr( $activity_id ); ?>">▱ <span><?php esc_html_e( 'Comment', 'social-discovery' ); ?></span></button><button type="button" data-sd-save="<?php echo esc_attr( $activity_id ); ?>" aria-pressed="<?php echo $saved ? 'true' : 'false'; ?>"><?php echo $saved ? '▣' : '□'; ?> <span><?php echo $saved ? esc_html__( 'Saved', 'social-discovery' ) : esc_html__( 'Save', 'social-discovery' ); ?></span></button><a href="<?php echo esc_url( sd_social_activity_url( $args['activity'] ) ); ?>">↗ <span><?php esc_html_e( 'Open', 'social-discovery' ); ?></span></a></div>
